/* V-52: the icon sprite of the game UI. One file of <symbol>s (24 grid, stroke 2.5, currentColor), inserted into the
   document once; a button draws an icon with <svg class="ic"><use href="#i-NAME"/></svg>. The file lives outside
   `assets/` (the provenance gate refuses that directory name) and is a first-party text material. */

import sprite from "./icons.svg?raw";

const NS = "http://www.w3.org/2000/svg";
const HOLDER = "ui-icon-sprite";

/** Put the sprite into the document, once; a second call is a no-op. */
export const installIcons = (doc: Document = document): void => {
  if (doc.getElementById(HOLDER)) return;
  const holder = doc.createElement("div");
  holder.id = HOLDER;
  holder.hidden = true;
  holder.setAttribute("aria-hidden", "true");
  holder.innerHTML = sprite;
  doc.body.prepend(holder);
};

/** The ids the sprite defines, e.g. `i-mic`. */
export const iconNames = (): string[] => [...sprite.matchAll(/<symbol id="([^"]+)"/g)].map((match) => match[1]);

/** An icon node: `icon("mic")` draws `#i-mic`. Decorative by default; the word beside it is the label. */
export const icon = (name: string, className = "ic"): SVGSVGElement => {
  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("class", className);
  svg.setAttribute("aria-hidden", "true");
  const use = document.createElementNS(NS, "use");
  use.setAttribute("href", `#i-${name}`);
  svg.append(use);
  return svg;
};
