/* V-52: the two-sided node (BRIEF rule 7, owner feedback 2026-11-02 item 1: «только на столе проверь чтобы все
   дублировалось»). On the flat table everything with words outside a seat exists twice: once facing each long side.

   The contract, which the both-sides oracle (tests/e2e/ui_oracles.py) enforces:
   - the NEAR copy carries `data-testid` (so a strict locator and `count()` still see ONE node per testid, as today)
     and `data-side="near"`;
   - the FAR copy carries `data-twin="<testid>"` and `data-side="far"` and NO testid; it is drawn by the same painter
     and presses the same handler, so either side reaches the one action (compare `table-approve-far`, which presses
     `table-approve`);
   - the far copy lives inside a host that is turned 180° as a whole (`.seats-far`, `[data-testid=rail-far]`); this
     module never rotates anything itself, so a node cannot be turned twice and read upright again.
   The historical far-side testids (`table-approve-far`, `rail-far`, `seats-far`) stay as they are. */

export type Side = "near" | "far";

export type TwinSpec = {
  /** The testid the near copy carries and the far copy points at with `data-twin`. */
  testid: string;
  tag?: keyof​ HTMLElementTagNameMap;
  className?: string;
  /** Draws a copy. The SAME painter runs for both, so the sides cannot drift apart. */
  paint: (el: HTMLElement, side: Side) => void;
  /** Pressed on either copy. */
  onPress?: (event: Event, side: Side) => void;
};

export type Twin = {
  near: HTMLElement;
  far: HTMLElement;
  /** Repaint both copies. */
  repaint: () => void;
  /** Attach the copies to their hosts. */
  mount: (nearHost: Element, farHost: Element) => void;
  /** Show or hide both copies together. */
  setHidden: (hidden: boolean) => void;
  remove: () => void;
};

export const makeTwin = (spec: TwinSpec): Twin => {
  const build = (side: Side): HTMLElement => {
    const el = document.createElement(spec.tag ?? "div");
    if (spec.className) el.className = spec.className;
    el.dataset.side = side;
    if (side === "near") el.dataset.testid = spec.testid;
    else el.dataset.twin = spec.testid;
    if (spec.onPress) {
      const handler = spec.onPress;
      el.addEventListener("click", (event) => handler(event, side));
    }
    return el;
  };
  const near = build("near");
  const far = build("far");
  const repaint = (): void => {
    spec.paint(near, "near");
    spec.paint(far, "far");
  };
  repaint();
  return {
    near,
    far,
    repaint,
    mount: (nearHost, farHost) => {
      nearHost.append(near);
      farHost.append(far);
    },
    setHidden: (hidden) => {
      near.hidden = hidden;
      far.hidden = hidden;
    },
    remove: () => {
      near.remove();
      far.remove();
    },
  };
};
